package com.portfolio.fraud.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="accounts") public class Account { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="account_number",unique=true,nullable=false) private String accountNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="account_type",nullable=false) private String accountType; @Column(nullable=false,precision=19,scale=2) private BigDecimal balance; @org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.CHAR) @Column(nullable=false,length=3) private String currency="USD"; @Enumerated(EnumType.STRING) @Column(nullable=false) private AccountStatus status=AccountStatus.ACTIVE; @Version private Long version; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected Account(){} public Account(String n,User u,String t,BigDecimal b){this(n,u,t,b,"USD");} public Account(String n,User u,String t,BigDecimal b,String c){accountNumber=n;user=u;accountType=t;balance=b;currency=c;} public Long getId(){return id;} public String getAccountNumber(){return accountNumber;} public User getUser(){return user;} public String getAccountType(){return accountType;} public BigDecimal getBalance(){return balance;} public String getCurrency(){return currency;} public AccountStatus getStatus(){return status;} public void credit(BigDecimal amount){balance=balance.add(amount);} public void debit(BigDecimal amount){balance=balance.subtract(amount);} }
